import{c as s,Q as a,j as i,m as t}from"./chunks/framework.g_l1frA7.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":null}'),o={name:"getting-started/installation.md"};function n(d,e,r,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>FinSight ships as a single Docker image. You do not compile it on the server.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Docker Engine and <code>docker compose</code> (bundled with recent Docker).</li><li>Disk for the image (a few hundred MB) plus your data (<code>/data</code> grows with CSV history; generous is cheap).</li><li>One of: Tailscale (recommended), a domain + Caddy, or just your LAN — see <a href="/FinSight/help/self-hosting">Self-Hosting</a>.</li></ul><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>From the repository root where <code>docker-compose.yml</code> lives:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Koushik0901/FinSight.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FinSight</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> finsight</span></span></code></pre></div><p>The first run pulls <code>ghcr.io/koushik0901/finsight:latest</code> (multi-arch: AMD64 + ARM64) and creates a named volume <code>finsight-data</code> for <code>/data</code>. The container is <code>read_only</code>, <code>no-new-privileges</code>, <code>cap_drop: ALL</code>, only <code>/data</code> and a small <code>tmpfs</code> are writable.</p><p>To build this checkout instead (development or local patches):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.build.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Open <code>http://localhost:8674</code> on the host to smoke-test. Then put it behind HTTPS for normal use — browsers require a secure context for the PWA, offline cache, and share-target.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Copy <code>finsight.env.example</code> to <code>.env</code> beside <code>docker-compose.yml</code> when you need to pin a version or change ports:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>FINSIGHT_IMAGE</code></td><td><code>ghcr.io/koushik0901/finsight:latest</code></td><td>Image tag/digest to deploy</td></tr><tr><td><code>FINSIGHT_HOST_PORT</code></td><td><code>8674</code></td><td>Host port</td></tr><tr><td><code>FINSIGHT_COOKIE_SECURE</code></td><td><code>1</code></td><td><code>Secure</code> on session cookies; set <code>0</code> only for bare-HTTP LAN testing</td></tr><tr><td><code>FINSIGHT_PUBLIC_ORIGIN</code></td><td>inferred</td><td>External HTTPS origin when proxy headers are insufficient</td></tr></tbody></table><p>Inside the container the server also respects <code>FINSIGHT_DATA_DIR</code> (<code>/data</code>), <code>FINSIGHT_UI_DIR</code> (<code>/app/ui/dist</code>), <code>FINSIGHT_PORT</code> (<code>8674</code>), and <code>RUST_LOG</code>.</p><h2 id="first-account" tabindex="-1">First account <a class="header-anchor" href="#first-account" aria-label="Permalink to &quot;First account&quot;">​</a></h2><p>The first visit to a fresh instance shows the setup wizard. The first account becomes the administrator and receives a <strong>one-time recovery key</strong>.</p><blockquote><p>Save the recovery key in a password manager or printed copy <em>immediately</em>. FinSight cannot reset it for you.</p></blockquote><p>After sign-in the admin can add non-admin users at <strong>Settings → Account → Manage users</strong>. Each receives a separate encrypted database and its own recovery key — the admin must hand it over securely.</p><p>Passwords must be at least 10 characters. Login and recovery share a per-username throttle: five failures → 60-second cooldown (including unknown usernames). Sessions have a sliding 30-day lifetime and survive restarts.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>For a pinned version, set <code>FINSIGHT_IMAGE</code> in <code>.env</code> to the release tag. Versioned GitHub Releases include a Compose file pinned to the same tag.</p><p>Back up <code>/data</code> before upgrading. Include <code>users.db</code>, <code>session.key</code>, and every <code>users/&lt;uuid&gt;/</code>.</p><p>Next: <a href="/FinSight/getting-started/first-launch">First Launch</a>.</p>`,25)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
